-- DRAFT FOR REVIEW. NOT APPLIED. Generated by scripts/tenancy/generate_migrations.py -- do not edit by hand.
-- Backlog 1.19, decision D-37: existing data belongs to tenant label 'default'; row-level security is the
-- second wall; BP staff get read-only, logged support access.
-- Part 2: relabel any row that still has no label
-- Needed for the 20 tables that already had a tenant_id column (some rows are NULL) and for rows inserted
-- between part 1 and the application change. Batched so no long lock is held; re-run until it reports 0.
-- Rows are never guessed: single-tenant today, so every NULL becomes 'default' (D-37 Q1).
-- Also builds the per-table index CONCURRENTLY (cannot run inside a transaction, so none is opened here).

CREATE OR REPLACE PROCEDURE pg_temp.bp_relabel(tbl regclass, batch int DEFAULT 20000)
LANGUAGE plpgsql AS $$
DECLARE n int;
BEGIN
  LOOP
    EXECUTE format('UPDATE %s SET tenant_id = %L WHERE ctid IN (SELECT ctid FROM %s WHERE tenant_id IS NULL LIMIT %s)',
                   tbl, 'default', tbl, batch);
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    COMMIT;
  END LOOP;
END $$;

